// HasTender applies the HasEdge predicate on the "tender" edge.
func HasTender() predicate.TenderSubmission {
	return predicate.TenderSubmission(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TenderTable, TenderColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTenderWith applies the HasEdge predicate on the "tender" edge with a given conditions (other predicates).
func HasTenderWith(preds ...predicate.Tender) predicate.TenderSubmission {
	return predicate.TenderSubmission(func(s *sql.Selector) {
		step := newTenderStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TenderSubmission) predicate.TenderSubmission {
	return predicate.TenderSubmission(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TenderSubmission) predicate.TenderSubmission {
	return predicate.TenderSubmission(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TenderSubmission) predicate.TenderSubmission {
	return predicate.TenderSubmission(sql.NotPredicates(p))
}
